#include <stdio.h>

int main(void) {
    int bowl[{n}];

    for (int i = 0; i < {n}; i++) {
        if (scanf("%d", &bowl[i]) != 1) {
            return 1;
        }
    }

    FILE *fp = fopen("dangan.bin", "wb");
    if (fp == NULL) {
        printf("打不开喵\n");
        return 0;
    }
    fwrite(bowl, sizeof(int), {n}, fp);
    fclose(fp);

    int back[{n}];
    for (int i = 0; i < {n}; i++) {
        back[i] = 0;
    }

    fp = fopen("dangan.bin", "rb");
    if (fp == NULL) {
        printf("读不到喵\n");
        return 0;
    }
    int got = (int)fread(back, sizeof(int), {n}, fp);
    fclose(fp);

    printf("读回来 %d 个数\n", got);
    for (int i = 0; i < {n}; i++) {
        printf("%d\n", back[i]);
    }
    return 0;
}
